// GENERATED by npm run client:sync. Edit packages/rules/src instead.
import type { GameState } from './game';
import { bombMultiplier } from './score';

/** White-list projection; never spreads GameState or PlayerState into a public object. */
export function createPublicView(state: GameState) {
  const turn = state.players[state.turnIndex];
  if (!turn) throw new RangeError('Invalid turn');
  return Object.freeze({
    version: state.version,
    status: state.status,
    pendingRule: state.pendingRule,
    rules: Object.freeze({ version: state.rules.version, deckCount: state.rules.deckCount,
      allowedBombSizes: Object.freeze([...state.rules.allowedBombSizes]), roundPointCap: state.rules.roundPointCap,
      straightMinLength: state.rules.straightMinLength, consecutivePairsMinLength: state.rules.consecutivePairsMinLength }),
    players: Object.freeze(state.players.map((player) => Object.freeze({
      playerId: player.playerId, handCount: player.hand.length,
    }))),
    turnPlayerId: turn.playerId,
    drawPileCount: state.drawPile.length,
    consecutivePasses: state.consecutivePasses,
    bombCount: state.bombCount,
    multiplier: bombMultiplier(state.bombCount),
    table: state.table ? Object.freeze({ playerId: state.table.playerId,
      cardIds: Object.freeze([...state.table.cardIds]),
      hand: Object.freeze({ kind: state.table.hand.kind, primaryRank: state.table.hand.primaryRank,
        cardCount: state.table.hand.cardCount, sequenceLength: state.table.hand.sequenceLength,
        wildAssignments: Object.freeze(state.table.hand.wildAssignments.map((assignment) => Object.freeze({
          cardId: assignment.cardId, rank: assignment.rank,
        }))) }),
    }) : null,
    settlement: state.settlement ? Object.freeze({ winnerId: state.settlement.winnerId,
      bombCount: state.settlement.bombCount, multiplier: state.settlement.multiplier, pointCap: state.settlement.pointCap,
      scores: Object.freeze(state.settlement.scores.map((score) => Object.freeze({
        playerId: score.playerId, remainingCards: score.remainingCards, delta: score.delta,
      }))),
    }) : null,
  });
}

/** Caller must bind playerId to authenticated identity; a playerId string is not authorization. */
export function createPlayerView(state: GameState, playerId: string) {
  const player = state.players.find((entry) => entry.playerId === playerId);
  if (!player) throw new RangeError('Unknown player');
  return Object.freeze({ public: createPublicView(state),
    hand: Object.freeze(player.hand.map((card) => Object.freeze({ cardId: card.cardId, deckIndex: card.deckIndex,
      kind: card.kind, suit: card.suit, rank: card.rank }))),
  });
}
